-- VELTRIX MASTER ACTUAL HISTORY RESTORE — 60 markets
-- Source: user-supplied actual-result ZIP archives, consolidated 2026-08-09.
-- Resets ONLY VELTRIX actual/prediction/audit data. Non-VELTRIX tables are untouched.
-- Keeps latest 20 actual occurrences per real market. Engine reads latest 10.
-- market_040 / market_041 are duplicate Hong Kong VIP labels and are deactivated.

begin;

delete from public.veltrix_forward_audit;
delete from public.veltrix_prediction_snapshots;
delete from public.veltrix_market_results;

update public.veltrix_markets
set active = case when market_key in ('market_040','market_041') then false else true end,
    updated_at = now()
where market_key ~ '^market_[0-9]{3}$';

delete from public.veltrix_market_aliases
where market_id in (select id from public.veltrix_markets where market_key in ('market_040','market_041'))
   or lower(trim(alias)) in (lower('หุ้นฮั่งเส็ง VIP เช้า'), lower('หุ้นฮั่งเส็ง VIP บ่าย'));

insert into public.veltrix_market_aliases (market_id, alias, active)
select m.id, x.alias, true
from (values
  ('market_046','หุ้นฮั่งเส็ง VIP เช้า'),
  ('market_047','หุ้นฮั่งเส็ง VIP บ่าย')
) x(market_key,alias)
join public.veltrix_markets m on m.market_key=x.market_key
on conflict do nothing;

-- Compact payload format after base64 decode: market number | YYMMDD | TOP3BOTTOM2
with encoded(b64) as (values (
$A$$A$ ||
$B$$B$ ||
$C$$C$ ||
$D$MDcyNXw2NjU1MQo2MnwyNjA3MjR8MDgyNDAKNjJ8MjYwNzIzfDc3MTkxCjYyfDI2MDcyMnw3MzUxMwo2MnwyNjA3MjF8ODA0MDU=$D$
)),
payload(data) as (
  select convert_from(decode(b64,'base64'),'UTF8') from encoded
),
seed as (
  select
    'market_' || lpad(split_part(line,'|',1),3,'0') as market_key,
    to_date('20' || split_part(line,'|',2),'YYYYMMDD') as draw_date,
    substr(split_part(line,'|',3),1,3) as top3,
    substr(split_part(line,'|',3),4,2) as bottom2
  from payload, regexp_split_to_table(trim(data), E'\n') as line
)
insert into public.veltrix_market_results
  (market_id, draw_date, top3, bottom2, source, import_batch_id)
select m.id, s.draw_date, s.top3, s.bottom2, 'master_actual_2026_08_09', null
from seed s
join public.veltrix_markets m on m.market_key=s.market_key
where m.active=true
on conflict (market_id,draw_date) do update
set top3=excluded.top3,
    bottom2=excluded.bottom2,
    source=excluded.source,
    import_batch_id=null,
    updated_at=now();

commit;

-- VERIFY
select count(*) as active_market_count from public.veltrix_markets where active=true; -- expected 60
select count(*) as actual_result_count from public.veltrix_market_results; -- expected 1200

select m.market_key,m.market_name,count(r.id) result_count
from public.veltrix_markets m
left join public.veltrix_market_results r on r.market_id=m.id
where m.active=true
group by m.market_key,m.market_name
having count(r.id)<>20
order by m.market_key;
-- expected 0 rows

select m.market_key,m.market_name,m.active,count(r.id) result_count
from public.veltrix_markets m
left join public.veltrix_market_results r on r.market_id=m.id
where m.market_key in ('market_040','market_041','market_046','market_047')
group by m.market_key,m.market_name,m.active
order by m.market_key;
-- 040/041 inactive + 0 rows; 046/047 active + 20 rows.

select m.market_name,r.draw_date,r.top3,r.bottom2
from public.veltrix_market_results r
join public.veltrix_markets m on m.id=r.market_id
where m.market_key='market_048'
order by r.draw_date desc limit 5;
-- HSI morning expected: 2026-08-07 785-57; 2026-08-06 351-31; 2026-08-05 120-28.
